import json,re,xml.etree.ElementTree as ET
from pathlib import Path
source=json.loads(Path('source.json').read_text())
answer=json.loads(Path('answer.json').read_text())
assert len(answer)==12
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
base={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
for s,a in zip(source,answer):
 assert all(s[k]==a[k] for k in ('code_id','source_id','source_sha256','number'))
 assert a['status']=='rewrite_draft'
 extras=set(a)-base
 if a.get('change_type')=='normative_reduction':
  assert extras=={'change_type','reform_policy_id','removed_provisions'}
  assert a['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(x)>=30 for x in a['removed_provisions'])
 elif a.get('change_type')=='full_repeal':
  assert extras=={'change_type','repeal_policy_id','repeal_scope'}
  assert a['repeal_policy_id']=='editorial_direction_2026_10_19'
  assert len(a['repeal_scope'])>=30
 else: assert not extras
 root=ET.fromstring('<root>'+a['proposed_xml']+'</root>')
 for e in list(root.iter())[1:]:
  assert e.tag in allowed
  assert all(k in ('rowspan','colspan') and re.fullmatch(r'\\d+',v) for k,v in e.attrib.items())
 assert all(a[k].strip() for k in ('proposed_xml','reason','review_notes'))
 if a.get('change_type')"'!='"'full_repeal':
  src_tables=s['source_xml'].count('<table')
  assert a['proposed_xml'].count('<table')==src_tables
 assert 'texte inchangé' not in a['proposed_xml'].lower()
print('Douze objets complets, identifiants exacts, XML et métadonnées conformes.')
print('Trois réductions normatives et une abrogation de doublon ; huit réécritures à droit constant motivées.')
print('answer.json :',Path('answer.json').stat().st_size,'octets')
for number in ('6','8'):
 a=next(a for a in answer if a['number']==number)
 root=ET.fromstring('<root>'+a['proposed_xml']+'</root>')
 if number=='6':
  print('Article 6, alinéas relus après correction :')
  for i in (0,1,14,19):print(i+1,root[i].text)
 else:
  print('Article 8, 2° relu après correction :',root[3].text)
PY"

